//! LRM-COVERS: 4.6.4.6
//!
//! lrm-conformance-wave3 (Phase 6, T36): §4.6.4.6 "Correlated noise" —
//! "Perfectly correlated noise is generated by using the output of one
//! noise function for more than one noise source." Both of the LRM's own
//! examples assign a `white_noise(...)` call to a variable once, then
//! contribute that variable on two separate branches:
//! `n = white_noise(pwr); V(a,b) <+ c1*n; V(c,d) <+ c2*n;`.
//!
//! Before this task, that exact idiom silently lost the noise term
//! entirely: `scan_noise` (`crates/piperine-codegen/src/resolve/pom/
//! expr.rs`) only attributes a `white_noise`/`flicker_noise` call to a
//! branch when it appears **directly** inside a `Contribution` statement's
//! own value — an assignment statement (`n = white_noise(pwr);`) is never
//! scanned, so `n`'s value silently resolved to a bare `0.0`
//! (`NoiseCall::lower`'s deterministic-residual substitution, correct for
//! the *direct*-contribution case but never reached by `scan_noise` here)
//! with no `NoiseSource` ever registered — a silent, CLAUDE.md-forbidden
//! drop of the entire correlated-noise idiom, not merely a missing test.
//!
//! Piperine's noise engine has no notion of a shared noise-source identity
//! across contributions (that would require the noise engine to track and
//! coherently sum the shared generator's transfer paths, a real feature,
//! not a coverage gap) — so this task's fix is the CLAUDE.md-mandated
//! floor, not the full clause: `resolve_call`'s new white_noise/
//! flicker_noise arm fails loud, citing §4.6.4.6, whenever a noise call
//! reaches it without having been scanned on its own contribution. This
//! target proves that guard fires on the LRM's own idiom and — the
//! necessary counter-proof — does NOT fire on the ordinary, fully
//! supported direct-contribution form the entire `spice/` stdlib uses.

fn elab_and_lower(src: &str) -> Result<std::collections::HashMap<String, piperine_codegen::resolve::LoweredBody>, String> {
    let design = piperine_lang::parse_and_elaborate(src, &piperine_lang::SourceMap::dummy())
        .map_err(|e| format!("elaboration failed: {e}"))?;
    piperine_codegen::resolve::lower_bodies(&design).map_err(|e| format!("{e}"))
}

/// §4.6.4.6's own "perfectly correlated" idiom: a noise call assigned to a
/// variable, then contributed on two separate branches. Not silently
/// zeroed — fails loud, naming the clause.
#[test]
fn variable_reused_noise_call_fails_loud_instead_of_silently_zeroing() {
    let src = "module dut (inout electrical a, inout electrical b, inout electrical c, inout electrical d);\n\
        parameter real pwr = 1e-20;\n\
        real n;\n\
        analog begin\n\
        n = white_noise(pwr);\n\
        V(a, b) <+ n;\n\
        V(c, d) <+ n;\n\
        end\n\
        endmodule\n";
    let err = elab_and_lower(src).expect_err("the correlated-noise idiom must fail loud, not silently lower");
    assert!(
        err.contains("correlated noise") && err.contains("4.6.4.6"),
        "the error must cite §4.6.4.6 and name the construct, got: {err}"
    );
}

/// The ordinary, fully supported direct-contribution form — every real
/// device model in `headers/spice/` uses exactly this shape — must keep
/// working: a `white_noise`/`flicker_noise` call written directly inside
/// its own contribution's value is scanned and registered normally, not
/// caught by the new guard.
#[test]
fn direct_contribution_noise_is_unaffected() {
    let src = "module dut (inout electrical p, inout electrical n);\n\
        parameter real pwr = 1e-20;\n\
        analog begin\n\
        I(p, n) <+ white_noise(pwr);\n\
        end\n\
        endmodule\n";
    let bodies = elab_and_lower(src).expect("the direct-contribution form must still lower cleanly");
    let noise = &bodies["dut"].analog.as_ref().expect("an analog body").noise;
    assert_eq!(noise.len(), 1, "the direct contribution must still register exactly one noise source, got {}", noise.len());
}
